async function loadPaginationSettings(){const {data}=await sqSupabase.from('app_settings').select('key,value').in('key',['posts_per_page','profiles_per_page']);for(const setting of data||[]){if(setting.key==='posts_per_page')postsPerPage=setting.value;if(setting.key==='profiles_per_page')profilesPerPage=setting.value;}}
