const initials = name => name.trim().split(/\s+/).map(word => word[0]).join('').slice(0,2).toUpperCase();
async function applyUser(user){currentUser=user;const fallbackName=user.user_metadata?.display_name||user.email.split('@')[0];const {data:profile}=await sqSupabase.from('profiles').select('display_name,username,xp,level,bio,avatar_url,is_admin').eq('id',user.id).maybeSingle();currentProfile={display_name:fallbackName,username:user.email.split('@')[0],onboarding_completed:true,is_admin:false,...profile};const name=currentProfile.display_name||fallbackName,first=name.split(' ')[0],avatar=initials(name);state.xp=currentProfile.xp||0;state.level=currentProfile.level||1;refreshProfile();document.querySelector('#navAvatar').textContent=avatar;document.querySelector('#profileAvatar').textContent=avatar;[document.querySelector('#navAvatar'),document.querySelector('#profileAvatar')].forEach(node=>{node.classList.toggle('photo',!!currentProfile.avatar_url);node.style.backgroundImage=currentProfile.avatar_url?`url(${currentProfile.avatar_url})`:''});document.querySelector('#navName').textContent=first;document.querySelector('#welcomeName').textContent=`WELCOME BACK, ${first.toUpperCase()}`;document.querySelector('#profileName').innerHTML=`${name} <span>✓</span>`;document.querySelector('#profileHandle').textContent=`@${currentProfile.username}`;document.querySelector('#authScreen').hidden=true;document.querySelector('#adminNav').hidden=!currentProfile.is_admin;await Promise.all([loadPosts(true),loadQuestProgress(),loadGroupQuest(),loadWhoToFollow(),loadTrendingQuests(),loadAdminCommunityQuests(),loadAdminBadges()])}
function setMode(mode){const signup=mode==='signup';document.querySelector('#authTitle').textContent=signup?'Create your account':'Welcome back';document.querySelector('#authSub').textContent=signup?'Start your SocialQuest adventure today.':'Sign in to continue your adventure.';document.querySelector('#authSubmit').textContent=signup?'Create account':'Sign in';document.querySelector('#nameField').hidden=!signup;document.querySelector('#authName').required=signup;document.querySelector('#authSwitch').innerHTML=signup?'Already a member? <button type="button" id="toggleAuth">Sign in</button>':'New to SocialQuest? <button type="button" id="toggleAuth">Create an account</button>';document.querySelector('#toggleAuth').onclick=()=>setMode(signup?'signin':'signup');document.querySelector('#authForm').dataset.mode=mode;document.querySelector('#authError').textContent=''}
async function initAuth(){const {data:{session}}=await sqSupabase.auth.getSession();if(session)await applyUser(session.user);else document.querySelector('#authScreen').hidden=false;setMode('signin');document.querySelector('#authForm').onsubmit=async e=>{e.preventDefault();const email=document.querySelector('#authEmail').value.trim().toLowerCase(),password=document.querySelector('#authPassword').value,name=document.querySelector('#authName').value.trim(),signup=e.currentTarget.dataset.mode==='signup',error=document.querySelector('#authError');error.textContent='';if(signup){if(!name)return error.textContent='Please enter your name.';const username=`${email.split('@')[0].replace(/[^a-z0-9_]/gi,'').toLowerCase()}_${Math.random().toString(36).slice(2,6)}`;const {data,error:authError}=await sqSupabase.auth.signUp({email,password,options:{data:{display_name:name,username}}});if(authError)return error.textContent=authError.message;if(!data.session){error.style.color='#4b8e72';error.textContent='Check your email to confirm your account, then sign in.';return}await applyUser(data.user);toast('Welcome to SocialQuest!')}else{const {data,error:authError}=await sqSupabase.auth.signInWithPassword({email,password});if(authError)return error.textContent=authError.message;await applyUser(data.user);toast('Welcome back!')}};document.querySelector('#signOut').onclick=async()=>{await sqSupabase.auth.signOut();currentUser=null;document.querySelector('#authForm').reset();document.querySelector('#authScreen').hidden=false;setMode('signin')};sqSupabase.auth.onAuthStateChange(async(event,session)=>{if(event==='SIGNED_IN'&&session)await applyUser(session.user)})}
initAuth();
