const toast = message => { const node = document.querySelector('#toast'); node.textContent = message; node.classList.add('show'); setTimeout(() => node.classList.remove('show'), 2600); };
function questMarkup(quest, i) { const goal=i===0?2:1,done=state.quests[i]>=goal;return `<article class="quest-card"><span class="quest-icon">${done?'✅':quest.icon}</span><div><h3>${quest.title}</h3><p>${quest.text}</p></div><div class="quest-meta"><span>${done?'Completed':`✦ +${quest.xp} XP`}</span><button disabled>${done?'Done':`${state.quests[i]} / ${goal}`}</button></div></article>`; }
function renderQuests() { const cards=document.querySelector('#questCards');if(cards)cards.innerHTML=quests.map((q,i)=>questMarkup(q,i)).join('');document.querySelector('#questList').innerHTML=quests.map((q,i)=>questMarkup(q,i)).join(''); }
function refreshProfile(){const levelXp=state.xp%3000;document.querySelector('#xpText').textContent=levelXp.toLocaleString('en-US');document.querySelector('#level').textContent=state.level;document.querySelector('#xpBar').style.width=`${levelXp/30}%`;const composerAvatar=document.querySelector('#composerAvatar');if(composerAvatar&&currentProfile){composerAvatar.textContent=initials(currentProfile.display_name||'Q');composerAvatar.classList.toggle('photo',!!currentProfile.avatar_url);composerAvatar.style.backgroundImage=currentProfile.avatar_url?`url(${currentProfile.avatar_url})`:'';}}
async function loadQuestProgress(){if(!currentUser)return;const [{data:allQuests},{data:progress}]=await Promise.all([sqSupabase.from('quests').select('id,title,goal').eq('active',true),sqSupabase.from('user_quests').select('quest_id,progress').eq('user_id',currentUser.id).eq('period_start',new Date().toISOString().slice(0,10))]);state.quests=quests.map(quest=>{const dbQuest=(allQuests||[]).find(item=>item.title===quest.title);return (progress||[]).find(item=>item.quest_id===dbQuest?.id)?.progress||0});renderQuests();const {data:profile}=await sqSupabase.from('profiles').select('xp,level').eq('id',currentUser.id).maybeSingle();if(profile){state.xp=profile.xp;state.level=profile.level;refreshProfile();}}
async function loadGroupQuest(){if(!currentUser)return;const {data:quest,error}=await sqSupabase.from('group_quests').select('id,title,description,goal,progress,xp_reward,active,group_quest_members(user_id)').order('created_at',{ascending:false}).limit(1).maybeSingle();const box=document.querySelector('#groupQuest');if(error||!quest){box.innerHTML='<p class="muted">No group quest is active right now.</p>';return;}const joined=(quest.group_quest_members||[]).some(member=>member.user_id===currentUser.id),percent=Math.min(100,quest.progress/quest.goal*100);box.innerHTML=`<article class="group-quest"><h3>✦ ${quest.title}</h3><p>${quest.description}</p><div class="xp-track"><span style="width:${percent}%"></span></div><div class="group-meta"><span>${quest.progress} / ${quest.goal} community stories · +${quest.xp_reward} XP</span><button class="${joined?'joined':''}" id="joinGroupQuest" ${joined?'disabled':''}>${joined?'Joined':'Join quest'}</button></div></article>`;const button=document.querySelector('#joinGroupQuest');if(button)button.addEventListener('click',async()=>{const {error:joinError}=await sqSupabase.rpc('join_group_quest',{quest_id:quest.id});if(joinError)return toast('Could not join the group quest.');await loadGroupQuest();toast('You joined the group quest! Publish to contribute.');});}
let posts = [];
const timeAgo = date => { const minutes=Math.max(1,Math.floor((Date.now()-new Date(date))/60000)); return minutes<60?`${minutes} min ago`:minutes<1440?`${Math.floor(minutes/60)}h ago`:`${Math.floor(minutes/1440)}d ago`; };
let feedMode='for-you';
async function loadPosts(){let authorIds=null;if(feedMode==='following'&&currentUser){const {data:follows}=await sqSupabase.from('follows').select('following_id').eq('follower_id',currentUser.id);authorIds=(follows||[]).map(row=>row.following_id);if(!authorIds.length){posts=[];renderPosts();return;}}let request=sqSupabase.from('posts').select('id,author_id,body,image_url,created_at,author:profiles!posts_author_id_fkey(display_name,username,avatar_url),post_reactions(count),comments(count)').order('created_at',{ascending:false}).limit(postsPerPage);if(authorIds)request=request.in('author_id',authorIds);const {data,error}=await request;if(error){console.warn(error.message);return;}posts=data.map(post=>({id:post.id,authorId:post.author_id,avatar:initials(post.author?.display_name||'Q'),color:'violet',name:post.author?.display_name||'Quest member',meta:`${post.author?.username?'@'+post.author.username+' · ':''}${timeAgo(post.created_at)}`,text:post.body,photo:post.image_url,likes:post.post_reactions?.[0]?.count||0,comments:post.comments?.[0]?.count||0}));renderPosts();}
function renderPosts(){ const empty=feedMode==='following'?'Follow people in Explore to see their posts here.':'No posts yet. Be the first to share an adventure!';document.querySelector('#feedPosts').innerHTML=posts.length?posts.map((p,i)=>`<article class="post"><div class="post-head"><span class="avatar ${p.color}">${p.avatar}</span><div><strong>${p.name}</strong><small>${p.meta}</small></div></div><p>${p.text}</p>${p.photo?`<div class="post-photo">${p.photo===true?'🌄':`<img src="${p.photo}" alt="Post image" />`}</div>`:''}<div class="post-actions"><button data-like="${i}">♡ ${p.likes}</button><button data-comments="${i}">◯ ${p.comments} comments</button><button data-report="${p.id||''}" class="report-btn">Report</button></div></article>`).join(''):`<p class="empty-people">${empty}</p>`;document.querySelectorAll('[data-like]').forEach(b=>b.addEventListener('click',()=>likePost(+b.dataset.like)));document.querySelectorAll('[data-comments]').forEach(b=>b.addEventListener('click',()=>openComments(+b.dataset.comments)));document.querySelectorAll('[data-report]').forEach(b=>b.addEventListener('click',()=>openReport(b.dataset.report))); }
async function likePost(index){const post=posts[index];if(!currentUser||!post.id)return toast('Sign in to react.');const {error}=await sqSupabase.from('post_reactions').insert({post_id:post.id,user_id:currentUser.id});if(error){if(error.code==='23505')return toast('You already liked this post.');return toast('Could not save your reaction.');}post.likes++;renderPosts();toast('You liked this adventure!');}
let people=[];
async function loadPeople(query=''){if(!currentUser)return;let request=sqSupabase.from('profiles').select('id,display_name,username,level').neq('id',currentUser.id).order('created_at',{ascending:false}).limit(profilesPerPage);if(query)request=request.or(`display_name.ilike.%${query}%,username.ilike.%${query}%`);const [{data:profiles,error},{data:follows}]=await Promise.all([request,sqSupabase.from('follows').select('following_id').eq('follower_id',currentUser.id)]);const list=document.querySelector('#peopleList');if(error){list.innerHTML='<p class="empty-people">Could not load people yet.</p>';return;}const following=new Set((follows||[]).map(row=>row.following_id));people=(profiles||[]).map(profile=>({...profile,following:following.has(profile.id)}));list.innerHTML=people.length?people.map((person,index)=>`<article class="person"><span class="avatar green">${initials(person.display_name)}</span><div class="person-info"><strong>${person.display_name}</strong><small>@${person.username} · Level ${person.level}</small></div><button class="follow-btn ${person.following?'following':''}" data-follow="${index}">${person.following?'Following':'Follow'}</button><button class="follow-btn following block-btn" data-block="${index}">Block</button></article>`).join(''):'<p class="empty-people">No Questers found. Invite your friends!</p>';document.querySelectorAll('[data-follow]').forEach(button=>button.addEventListener('click',()=>toggleFollow(+button.dataset.follow)));document.querySelectorAll('[data-block]').forEach(button=>button.addEventListener('click',()=>blockUser(+button.dataset.block)));}
async function toggleFollow(index){const person=people[index];if(!person||!currentUser)return;const wasFollowing=person.following;const request=wasFollowing?sqSupabase.from('follows').delete().eq('follower_id',currentUser.id).eq('following_id',person.id):sqSupabase.from('follows').insert({follower_id:currentUser.id,following_id:person.id});const {error}=await request;if(error)return toast('Could not update your follow.');await Promise.all([loadPeople(document.querySelector('#peopleSearch').value.trim()),loadQuestProgress()]);toast(wasFollowing?`You unfollowed ${person.display_name}.`:`You are now following ${person.display_name}.`);}
let reportedPostId=null;
function openReport(postId){if(!postId)return toast('Only community posts can be reported.');reportedPostId=postId;document.querySelector('#reportDialog').showModal();}
async function blockUser(index){const person=people[index];if(!person||!currentUser)return;const {error}=await sqSupabase.from('blocks').insert({blocker_id:currentUser.id,blocked_id:person.id});if(error){if(error.code==='23505')return toast('This person is already blocked.');return toast('Could not block this person.');}toast(`${person.display_name} has been blocked.`);await loadPeople(document.querySelector('#peopleSearch').value.trim());}
async function openNotifications(){if(!currentUser)return;const dialog=document.querySelector('#notificationsDialog'),list=document.querySelector('#notificationsList');dialog.showModal();list.innerHTML='<p class="empty-notifications">Loading notifications...</p>';const {data,error}=await sqSupabase.from('notifications').select('id,kind,read_at,created_at,actor:profiles!notifications_actor_id_fkey(display_name)').eq('recipient_id',currentUser.id).order('created_at',{ascending:false}).limit(5);if(error){list.innerHTML='<p class="empty-notifications">Could not load notifications yet.</p>';return;}const action={reaction:'liked your post',comment:'commented on your post',follow:'started following you',quest:'completed a quest'};list.innerHTML=data.length?data.map(item=>`<article class="notification ${item.read_at?'':'unread'}"><span class="avatar pink">${initials(item.actor?.display_name||'Q')}</span><p><strong>${item.actor?.display_name||'A Quester'}</strong> ${action[item.kind]||'interacted with you'}<br><time>${timeAgo(item.created_at)}</time></p></article>`).join(''):'<p class="empty-notifications">No notifications yet.</p>';const unread=data.filter(item=>!item.read_at).map(item=>item.id);if(unread.length)await sqSupabase.from('notifications').update({read_at:new Date().toISOString()}).in('id',unread);}
async function loadAdminReports(){if(!currentProfile?.is_admin)return;const {data,error}=await sqSupabase.from('reports').select('id,post_id,reason,details,status,created_at,reporter:profiles!reports_reporter_id_fkey(display_name)').in('status',['open','reviewing']).order('created_at',{ascending:false});const box=document.querySelector('#adminReports');if(error){box.innerHTML='<p class="empty-people">Could not load reports.</p>';return;}box.innerHTML=(data||[]).length?data.map(report=>`<article class="admin-report"><h3>${report.reason.replace('_',' ')} report</h3><p>${report.details||'No extra details provided.'}</p><small>From ${report.reporter?.display_name||'Quester'} · ${timeAgo(report.created_at)}</small><div class="admin-actions"><button data-resolve="${report.id}">Resolve</button>${report.post_id?`<button class="danger" data-hide-post="${report.post_id}" data-resolve-report="${report.id}">Hide post</button>`:''}</div></article>`).join(''):'<p class="empty-people">No open reports. The community is all clear.</p>';document.querySelectorAll('[data-resolve]').forEach(button=>button.addEventListener('click',()=>resolveReport(button.dataset.resolve)));document.querySelectorAll('[data-hide-post]').forEach(button=>button.addEventListener('click',()=>hideReportedPost(button.dataset.hidePost,button.dataset.resolveReport)));}
async function loadAdminDashboard(){if(!currentProfile?.is_admin)return;const [{count:users},{count:postCount},{count:reports}]=await Promise.all([sqSupabase.from('profiles').select('*',{count:'exact',head:true}),sqSupabase.from('posts').select('*',{count:'exact',head:true}),sqSupabase.from('reports').select('*',{count:'exact',head:true}).in('status',['open','reviewing'])]);document.querySelector('#adminStats').innerHTML=`<article><strong>${users||0}</strong><span>Users</span></article><article><strong>${postCount||0}</strong><span>Posts</span></article><article><strong>${reports||0}</strong><span>Open reports</span></article>`;}
async function loadAdminUsers(query=''){if(!currentProfile?.is_admin)return;let request=sqSupabase.from('profiles').select('id,display_name,username,level,moderation_status,moderation_note,avatar_url,created_at').order('created_at',{ascending:false}).limit(20);if(query)request=request.or(`display_name.ilike.%${query}%,username.ilike.%${query}%`);const {data,error}=await request;const box=document.querySelector('#adminUsers');if(error){box.innerHTML='<p class="empty-people">Run admin-users.sql to enable user controls.</p>';return;}box.innerHTML=(data||[]).length?data.map(user=>`<article class="admin-user" data-admin-profile="${user.id}">${avatarMarkup(user.display_name,user.avatar_url)}<div><strong>${user.display_name}${user.id===currentUser?.id?' (you)':''}</strong><small>@${user.username} · Level ${user.level} · ${user.moderation_status}</small>${user.moderation_note?`<em>${user.moderation_note}</em>`:''}</div>${user.id===currentUser?.id?'':`<div class="admin-actions"><button data-user-status="${user.id}" data-status="warned">Warn</button><button data-user-status="${user.id}" data-status="suspended">Suspend</button><button class="danger" data-user-status="${user.id}" data-status="banned">Ban</button>${user.moderation_status!=='active'?`<button data-user-status="${user.id}" data-status="active">Restore</button>`:''}</div>`}</article>`).join(''):'<p class="empty-people">No users found.</p>';}
async function updateUserModeration(userId,status){const {error}=await sqSupabase.from('profiles').update({moderation_status:status,moderation_note:null,moderated_at:new Date().toISOString()}).eq('id',userId);if(error)return toast(`Could not update user: ${error.message}`);await loadAdminUsers(document.querySelector('#adminUserSearch').value.trim());toast(`User marked as ${status}.`);}
async function loadAdminQuests(){if(!currentProfile?.is_admin)return;const {data,error}=await sqSupabase.from('quests').select('id,title,description,icon,xp_reward,goal,cadence,active').order('created_at',{ascending:false});const box=document.querySelector('#adminQuests');if(error){box.innerHTML='<p class="empty-people">Run admin-quests.sql to enable quest management.</p>';return;}box.innerHTML=(data||[]).map(quest=>`<article class="admin-quest"><span>${quest.icon}</span><div><strong>${quest.title}</strong><small>${quest.description} · ${quest.goal} goal · +${quest.xp_reward} XP · ${quest.cadence}</small></div><button data-quest-toggle="${quest.id}" data-quest-active="${quest.active}">${quest.active?'Active':'Inactive'}</button><button class="danger" data-quest-delete="${quest.id}">Delete</button></article>`).join('')||'<p class="empty-people">No quests yet.</p>';document.querySelectorAll('[data-quest-toggle]').forEach(button=>button.addEventListener('click',()=>toggleAdminQuest(button.dataset.questToggle,button.dataset.questActive==='true')));document.querySelectorAll('[data-quest-delete]').forEach(button=>button.addEventListener('click',()=>deleteAdminQuest(button.dataset.questDelete)));}
async function toggleAdminQuest(id,active){const {error}=await sqSupabase.from('quests').update({active:!active}).eq('id',id);if(error)return toast('Could not update quest.');await loadAdminQuests();toast(active?'Quest paused.':'Quest activated.');}
async function deleteAdminQuest(id){if(!confirm('Delete this quest permanently?'))return;const {error}=await sqSupabase.from('quests').delete().eq('id',id);if(error)return toast('Could not delete quest.');await loadAdminQuests();toast('Quest deleted.');}
async function resolveReport(id){const {error}=await sqSupabase.from('reports').update({status:'resolved'}).eq('id',id);if(error)return toast('Could not resolve this report.');await loadAdminReports();toast('Report resolved.');}
async function hideReportedPost(postId,reportId){const {error}=await sqSupabase.from('posts').update({hidden:true}).eq('id',postId);if(error)return toast('Could not hide this post.');await resolveReport(reportId);await loadPosts();toast('Post hidden and report resolved.');}
async function openUserProfile(userId){if(!userId)return;const [{data:profile},{count:postCount},{count:followerCount},{count:followingCount},{data:recentPosts}]=await Promise.all([sqSupabase.from('profiles').select('display_name,username,bio,avatar_url,level,xp').eq('id',userId).maybeSingle(),sqSupabase.from('posts').select('*',{count:'exact',head:true}).eq('author_id',userId),sqSupabase.from('follows').select('*',{count:'exact',head:true}).eq('following_id',userId),sqSupabase.from('follows').select('*',{count:'exact',head:true}).eq('follower_id',userId),sqSupabase.from('posts').select('body,created_at').eq('author_id',userId).order('created_at',{ascending:false}).limit(3)]);if(!profile)return toast('Could not open this profile.');const avatar=profile.avatar_url?`<span class="avatar photo" style="background-image:url(${profile.avatar_url})">${initials(profile.display_name)}</span>`:`<span class="avatar amber">${initials(profile.display_name)}</span>`;document.querySelector('#userProfileContent').innerHTML=`<section class="user-profile-head">${avatar}<h2>${profile.display_name}</h2><p>@${profile.username} · Level ${profile.level}</p></section>${profile.bio?`<p class="user-profile-bio">${profile.bio}</p>`:''}<div class="user-profile-stats"><div><strong>${postCount||0}</strong><small>Posts</small></div><div><strong>${followerCount||0}</strong><small>Followers</small></div><div><strong>${followingCount||0}</strong><small>Following</small></div></div><section>${(recentPosts||[]).length?(recentPosts||[]).map(post=>`<p class="user-post-preview">${post.body}</p>`).join(''):'<p class="empty-people">No posts yet.</p>'}</section>`;document.querySelector('#userProfileDialog').showModal();}
let activeConversation=null,chatSubscription=null;
async function loadMessagePeople(query=''){if(!currentUser)return;let request=sqSupabase.from('profiles').select('id,display_name,username,avatar_url').neq('id',currentUser.id).order('created_at',{ascending:false}).limit(profilesPerPage);if(query)request=request.or(`display_name.ilike.%${query}%,username.ilike.%${query}%`);const {data,error}=await request;const list=document.querySelector('#messagePeople');if(error){list.innerHTML='<p class="empty-people">Could not load people.</p>';return;}list.innerHTML=(data||[]).length?data.map((person,index)=>`<button class="message-person" data-message-person="${index}"><span class="avatar green">${initials(person.display_name)}</span><strong>${person.display_name}<small> @${person.username}</small></strong></button>`).join(''):'<p class="empty-people">No people found.</p>';document.querySelectorAll('[data-message-person]').forEach(button=>button.addEventListener('click',()=>startConversation(data[+button.dataset.messagePerson])));}
async function startConversation(person){const {data:conversation,error}=await sqSupabase.rpc('get_or_create_direct_conversation',{recipient_id:person.id});if(error)return toast('Could not start this conversation.');activeConversation=conversation;document.querySelector('#chatBox').hidden=false;document.querySelector('#messageEmptyState')?.setAttribute('hidden','');document.querySelector('#chatName').textContent=person.display_name;document.querySelector('#chatAvatar').textContent=initials(person.display_name);if(person.avatar_url)document.querySelector('#chatAvatar').style.backgroundImage=`url(${person.avatar_url})`;else document.querySelector('#chatAvatar').style.backgroundImage='';await markConversationRead(conversation);await loadMessages();await loadConversationInbox();await refreshUnreadMessages();if(chatSubscription)sqSupabase.removeChannel(chatSubscription);chatSubscription=sqSupabase.channel(`chat-${conversation}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:`conversation_id=eq.${conversation}`},async()=>{await loadMessages();await loadConversationInbox();await refreshUnreadMessages();}).subscribe();}
async function loadMessages(){if(!activeConversation)return;const {data,error}=await sqSupabase.from('messages').select('id,sender_id,body,created_at').eq('conversation_id',activeConversation).order('created_at');const history=document.querySelector('#chatHistory');if(error){history.innerHTML='<p class="empty-people">Could not load messages.</p>';return;}history.innerHTML=(data||[]).map(message=>`<div class="bubble ${message.sender_id===currentUser.id?'mine':''}">${message.body}</div>`).join('')||'<p class="empty-people">Say hello!</p>';history.scrollTop=history.scrollHeight;}
