async function openComments(index){const post=posts[index];if(!post.id)return toast('Comments are available on community posts.');activePostId=post.id;document.querySelector('#commentsDialog').showModal();const list=document.querySelector('#commentsList');list.innerHTML='<p class="no-comments">Loading comments...</p>';const {data,error}=await sqSupabase.from('comments').select('body,created_at,author:profiles!comments_author_id_fkey(display_name)').eq('post_id',post.id).order('created_at');if(error){list.innerHTML='<p class="no-comments">Could not load comments.</p>';return;}list.innerHTML=data.length?data.map(comment=>`<article class="comment"><span class="avatar blue">${initials(comment.author?.display_name||'Q')}</span><div><strong>${comment.author?.display_name||'Quest member'}</strong><small>${timeAgo(comment.created_at)}</small><p>${comment.body}</p></div></article>`).join(''):'<p class="no-comments">No comments yet. Start the conversation!</p>';}
