// Standalone pages: every main area has its own address instead of a hash route.
const pageForView={feed:'feed.html',quests:'quests.html',explore:'explore.html',rank:'rankings.html',messages:'messages.html',admin:'admin.html'};
function activateStandaloneView(view){
  const selected=view||'feed';
  document.querySelectorAll('.view').forEach(item=>item.classList.toggle('active',item.id===selected));
  document.querySelectorAll('.nav-link,[data-view]').forEach(item=>item.classList.toggle('active',item.dataset.view===selected));
  if(selected==='explore')loadPeople();
  if(selected==='messages')loadMessagePeople();
  if(selected==='quests')loadGroupQuest();
  if(selected==='rank')loadRankings();
  if(selected==='admin'){loadAdminReports();loadAdminDashboard();loadAdminUsers();loadAdminQuests();}
}
async function openUserProfile(userId){
  if(!userId)return;
  const [{data:profile},{count:postCount},{count:followerCount},{count:followingCount},{data:recentPosts}]=await Promise.all([
    sqSupabase.from('profiles').select('display_name,username,bio,avatar_url,level').eq('id',userId).maybeSingle(),
    sqSupabase.from('posts').select('*',{count:'exact',head:true}).eq('author_id',userId),
    sqSupabase.from('follows').select('*',{count:'exact',head:true}).eq('following_id',userId),
    sqSupabase.from('follows').select('*',{count:'exact',head:true}).eq('follower_id',userId),
    sqSupabase.from('posts').select('body').eq('author_id',userId).order('created_at',{ascending:false}).limit(postsPerPage)
  ]);
  if(!profile)return toast('Could not open this profile.');
  if(!location.pathname.endsWith('/profile.html')){location.href=`profile.html?u=${encodeURIComponent(profile.username)}`;return;}
  const avatar=profile.avatar_url?`<span class="avatar photo" style="background-image:url(${profile.avatar_url})">${initials(profile.display_name)}</span>`:`<span class="avatar amber">${initials(profile.display_name)}</span>`;
  document.querySelector('#userProfilePage').innerHTML=`<div class="profile-page-cover"></div><div class="profile-page-main">${avatar}<h1>${profile.display_name}</h1><p class="handle">@${profile.username} · Level ${profile.level}</p>${profile.bio?`<p class="bio">${profile.bio}</p>`:''}<div class="user-profile-stats"><div><strong>${postCount||0}</strong><small>Posts</small></div><div><strong>${followerCount||0}</strong><small>Followers</small></div><div><strong>${followingCount||0}</strong><small>Following</small></div></div><section class="profile-page-posts"><h2>Posts</h2>${(recentPosts||[]).length?recentPosts.map(post=>`<article>${post.body}</article>`).join(''):'<p class="empty-people">No posts yet.</p>'}</section></div>`;
  activateStandaloneView('user-profile');
  window.scrollTo({top:0,behavior:'smooth'});
}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',event=>{
  const destination=pageForView[button.dataset.view];
  if(!destination)return;
  event.preventDefault();
  if(location.pathname.endsWith(`/${destination}`))activateStandaloneView(button.dataset.view);
  else location.href=destination;
}));
document.querySelector('#backToFeed').addEventListener('click',event=>{event.preventDefault();location.href='feed.html';});
window.addEventListener('load',()=>setTimeout(async()=>{
  const file=location.pathname.split('/').pop()||'index.html';
  if(file==='profile.html'){
    const username=new URLSearchParams(location.search).get('u');
    if(username){const {data}=await sqSupabase.from('profiles').select('id').eq('username',username).maybeSingle();if(data)await openUserProfile(data.id);}
    else if(currentUser)await openUserProfile(currentUser.id);
    document.body.classList.add('page-ready');
    return;
  }
  const view=file.startsWith('admin-')?'admin':(Object.entries(pageForView).find(([,page])=>page===file)?.[0]||'feed');
  activateStandaloneView(view);
  document.body.classList.add('page-ready');
},650));
new MutationObserver(()=>{const page=document.querySelector('#userProfilePage'),main=page.querySelector('.profile-page-main');if(!main||main.querySelector('.profile-badges'))return;const own=main.querySelector('h1')?.textContent===currentProfile?.display_name;const badges=document.createElement('div');badges.className='profile-badges';badges.innerHTML=`<div class="profile-badge">⚔<strong>${main.querySelector('.handle')?.textContent.match(/Level (\d+)/)?.[0]||'Level 1'}</strong></div><div class="profile-badge">✨<strong>Community Quester</strong></div><div class="profile-badge">🏆<strong>Early Explorer</strong></div>`;main.querySelector('.profile-page-posts')?.before(badges);if(own){const actions=document.createElement('div');actions.className='profile-actions';actions.innerHTML='<button id="profileEditShortcut">Edit profile</button>';main.querySelector('.profile-badges')?.before(actions);document.querySelector('#profileEditShortcut').addEventListener('click',()=>document.querySelector('#editProfile').click());}}).observe(document.querySelector('#userProfilePage'),{childList:true,subtree:true});
