const profilePostCard=(post,index)=>`<article class="post profile-post"><div class="post-head"><span class="avatar violet ${post.avatarUrl?'photo':''}" ${post.avatarUrl?`style="background-image:url(${post.avatarUrl})"`:''}>${post.avatar}</span><div><strong>${post.name}</strong><small>${post.meta}</small></div>${post.authorId===currentUser?.id?`<div class="post-menu"><button class="post-menu-trigger" data-profile-menu="${index}" aria-label="Post options">•••</button><div class="post-menu-panel" data-profile-menu-panel="${index}" hidden><button data-profile-edit="${index}">Edit</button><button class="danger" data-profile-delete="${index}">Delete post</button></div></div>`:''}</div><p>${post.text}</p>${post.photo?mediaMarkup(post.photo):''}<div class="post-actions"><button data-profile-like="${index}">♡ ${post.likes}</button><button data-profile-comments="${index}">◯ ${post.comments} comments</button><button data-profile-share="${index}">↗ Share</button><button data-profile-report="${post.id}" class="report-btn">Report</button></div></article>`;
