async function openUserProfile(userId){
  if(!userId)return;
  const [{data:profile},{count:postCount},{count:followerCount},{count:followingCount},{data:profilePosts}]=await Promise.all([
    sqSupabase.from('profiles').select('display_name,username,bio,avatar_url,level').eq('id',userId).maybeSingle(),
    sqSupabase.from('posts').select('*',{count:'exact',head:true}).eq('author_id',userId),
    sqSupabase.from('follows').select('*',{count:'exact',head:true}).eq('following_id',userId),
    sqSupabase.from('follows').select('*',{count:'exact',head:true}).eq('follower_id',userId),
    sqSupabase.from('posts').select('id,author_id,body,image_url,created_at,post_reactions(count),comments(count)').eq('author_id',userId).order('created_at',{ascending:false}).range(0,postsPerPage-1)
  ]);
  if(!profile)return toast('Could not open this profile.');
  if(!location.pathname.endsWith('/profile.html')){location.href=`profile.html?u=${encodeURIComponent(profile.username)}`;return;}
  const mapProfilePost=post=>({id:post.id,authorId:userId,avatar:initials(profile.display_name),avatarUrl:profile.avatar_url||null,color:'violet',name:profile.display_name,meta:`@${profile.username} · ${timeAgo(post.created_at)}`,text:post.body,photo:post.image_url,likes:post.post_reactions?.[0]?.count||0,comments:post.comments?.[0]?.count||0});
  profilePostState={userId,profile,mapProfilePost,offset:(profilePosts||[]).length,hasMore:(profilePosts||[]).length===postsPerPage,loading:false,items:(profilePosts||[]).map(mapProfilePost)};
  const avatar=profile.avatar_url?`<span class="avatar photo" style="background-image:url(${profile.avatar_url})">${initials(profile.display_name)}</span>`:`<span class="avatar amber">${initials(profile.display_name)}</span>`;
  const profileActions=userId===currentUser?.id?'<div class="profile-main-actions"><button id="profilePostShortcut">＋ New post</button></div>':`<div class="profile-main-actions"><button id="profileMessageShortcut">✉ Message</button></div>`;
  document.querySelector('#userProfilePage').innerHTML=`<div class="profile-page-cover"></div><div class="profile-page-main">${avatar}<h1>${profile.display_name}</h1><p class="handle">@${profile.username} · Level ${profile.level}</p>${profileActions}${profile.bio?`<p class="bio">${profile.bio}</p>`:''}<div class="user-profile-stats"><div><strong>${postCount||0}</strong><small>Posts</small></div><div><strong>${followerCount||0}</strong><small>Followers</small></div><div><strong>${followingCount||0}</strong><small>Following</small></div></div><section class="profile-badges" aria-label="Badge collection"><section class="badge-collection"><h3>Badge collection</h3><p>Complete quests and connect with people to unlock these achievements.</p><div><article class="collection-badge locked"><img class="badge-art" src="assets/badges/first-post.png" alt="First Story" /><span><strong>First Story</strong><small>Locked</small></span></article><article class="collection-badge locked"><img class="badge-art" src="assets/badges/first-comment.png" alt="Conversation Starter" /><span><strong>Conversation Starter</strong><small>Locked</small></span></article><article class="collection-badge locked"><img class="badge-art" src="assets/badges/first-like.png" alt="Appreciator" /><span><strong>Appreciator</strong><small>Locked</small></span></article><article class="collection-badge locked"><img class="badge-art" src="assets/badges/social-starter.png" alt="Social Starter" /><span><strong>Social Starter</strong><small>Locked</small></span></article><article class="collection-badge locked"><img class="badge-art" src="assets/badges/quest-master.png" alt="Quest Master" /><span><strong>Quest Master</strong><small>Locked</small></span></article><article class="collection-badge locked"><img class="badge-art" src="assets/badges/community-hero.png" alt="Community Hero" /><span><strong>Community Hero</strong><small>Locked</small></span></article></div></section></section><section class="profile-page-posts"><h2>Posts</h2><div class="profile-post-items"></div></section></div>`;
  document.querySelector('#profilePostShortcut')?.addEventListener('click',()=>document.querySelector('#postDialog').showModal());
  document.querySelector('#profileMessageShortcut')?.addEventListener('click',()=>{location.href=`messages.html?u=${encodeURIComponent(profile.username)}`;});
  renderProfilePostItems();loadProfileBadges(userId);activateStandaloneView('user-profile');window.scrollTo({top:0,behavior:'smooth'});
}
