async function loadProfileBadges(userId){
  const box=document.querySelector('.profile-badges');
  if(!box||!userId)return;
  const {data}=await sqSupabase.from('user_badges').select('badge:badges(code,name,description,icon)').eq('user_id',userId);
  const earned=data||[],earnedCodes=new Set(earned.map(item=>item.badge?.code));
  box.innerHTML=`<section class="earned-badges"><h3>Earned badges</h3>${earned.length?earned.map(item=>`<article class="profile-badge real-badge">${badgeArtwork(item.badge)}<div><strong>${item.badge.name}</strong><small>${item.badge.description}</small></div></article>`).join(''):'<p class="no-badges">No badges earned yet.</p>'}</section><section class="badge-collection"><h3>Badge collection</h3><p>Complete quests and connect with people to unlock these achievements.</p><div>${profileBadgeCatalog.map(badge=>`<article class="collection-badge ${earnedCodes.has(badge.code)?'earned':'locked'}">${badgeArtwork(badge)}<span><strong>${badge.name}</strong><small>${earnedCodes.has(badge.code)?'Unlocked':'Locked'}</small></span></article>`).join('')}</div></section>`;
}
async function loadConversationInbox(){
  const list=document.querySelector('#conversationList');
  if(!list||!currentUser)return;
  const {data:members,error}=await sqSupabase.from('conversation_members').select('conversation_id,user_id').neq('user_id',currentUser.id).limit(100);
  if(error){list.innerHTML='<p class="empty-people">Your conversations could not be loaded.</p>';return;}
  const conversationIds=[...new Set((members||[]).map(item=>item.conversation_id))];
  if(!conversationIds.length){list.innerHTML='<p class="empty-people">No conversations yet.</p>';return;}
  const partnerIds=[...new Set((members||[]).map(item=>item.user_id))];
  const [{data:people},{data:recentMessages}]=await Promise.all([
    sqSupabase.from('profiles').select('id,display_name,username,avatar_url').in('id',partnerIds),
    sqSupabase.from('messages').select('conversation_id,body,created_at').in('conversation_id',conversationIds).order('created_at',{ascending:false}).limit(150)
  ]);
  const peopleById=new Map((people||[]).map(person=>[person.id,person]));
  const latestByConversation=new Map();
  (recentMessages||[]).forEach(message=>{if(!latestByConversation.has(message.conversation_id))latestByConversation.set(message.conversation_id,message);});
  const entries=(members||[]).map(member=>({conversationId:member.conversation_id,person:peopleById.get(member.user_id),last:latestByConversation.get(member.conversation_id)})).filter(item=>item.person).sort((a,b)=>new Date(b.last?.created_at||0)-new Date(a.last?.created_at||0));
  list.innerHTML=entries.length?entries.map((entry,index)=>`<button class="conversation-row ${entry.conversationId===activeConversation?'active':''}" data-conversation-row="${index}">${avatarMarkup(entry.person.display_name,entry.person.avatar_url,'violet')}<span><strong>${entry.person.display_name}</strong><small>${entry.last?entry.last.body:'Start the conversation'}</small></span><time>${entry.last?timeAgo(entry.last.created_at):''}</time></button>`).join(''):'<p class="empty-people">No conversations yet.</p>';
  list.querySelectorAll('[data-conversation-row]').forEach(button=>button.addEventListener('click',()=>startConversation(entries[+button.dataset.conversationRow].person)));
}

function messageUnreadBadge(){
  const badges=[];
  document.querySelectorAll('[data-view="messages"]').forEach(button=>{
    let badge=button.querySelector('.message-unread-badge');
    if(!badge){badge=document.createElement('b');badge.className='message-unread-badge';button.append(badge);}
    badges.push(badge);
  });
  return badges;
}

async function markConversationRead(conversationId=activeConversation){
  if(!conversationId||!currentUser)return;
  await sqSupabase.from('conversation_members').update({last_read_at:new Date().toISOString()}).eq('conversation_id',conversationId).eq('user_id',currentUser.id);
}

async function refreshUnreadMessages(){
  if(!currentUser)return;
  const {data:members,error}=await sqSupabase.from('conversation_members').select('conversation_id,last_read_at').eq('user_id',currentUser.id).limit(100);
  if(error)return;
  const ids=(members||[]).map(member=>member.conversation_id);
  let unread=0;
  if(ids.length){
    const {data:messages}=await sqSupabase.from('messages').select('conversation_id,sender_id,created_at').in('conversation_id',ids).neq('sender_id',currentUser.id).order('created_at',{ascending:false}).limit(200);
    const readTimes=new Map((members||[]).map(member=>[member.conversation_id,new Date(member.last_read_at||0).getTime()]));
    unread=(messages||[]).filter(message=>new Date(message.created_at).getTime()>(readTimes.get(message.conversation_id)||0)).length;
  }
  messageUnreadBadge().forEach(badge=>{badge.hidden=unread===0;badge.textContent=unread>99?'99+':unread;});
}

async function openMessageRecipientFromUrl(){
  if(!location.pathname.endsWith('/messages.html')||!currentUser)return;
  const username=new URLSearchParams(location.search).get('u');
  if(!username)return;
  const {data:person}=await sqSupabase.from('profiles').select('id,display_name,username,avatar_url').eq('username',username).neq('id',currentUser.id).maybeSingle();
  if(person)await startConversation(person);
}

function initialiseMessagesPage(){
  if(!location.pathname.endsWith('/messages.html')||!currentUser||document.body.dataset.messagesReady)return;
  document.body.dataset.messagesReady='true';
  loadConversationInbox();
  loadMessagePeople();
  refreshUnreadMessages();
  openMessageRecipientFromUrl();
}

if(location.pathname.endsWith('/messages.html')){
  const messagesReadyTimer=setInterval(()=>{if(currentUser){clearInterval(messagesReadyTimer);initialiseMessagesPage();}},150);
}

const unreadBootTimer=setInterval(()=>{if(currentUser){clearInterval(unreadBootTimer);refreshUnreadMessages();}},250);
setInterval(()=>{if(currentUser)refreshUnreadMessages();},30000);

const postMediaInput=document.querySelector('#postImage');
let postVideoPreviewUrl='';
function resetPostMediaPreview(){
  const preview=document.querySelector('#postImagePreview'),image=document.querySelector('#postPreviewImage'),video=document.querySelector('#postPreviewVideo');
  if(postVideoPreviewUrl){URL.revokeObjectURL(postVideoPreviewUrl);postVideoPreviewUrl='';}
  image?.removeAttribute('src');
  if(video){video.pause();video.removeAttribute('src');video.hidden=true;}
  if(preview)preview.hidden=true;
}
function clearVideoPostSelection(){
  postMediaInput.value='';
  resetPostMediaPreview();
  document.querySelector('#imageLabel').textContent='Add photo or video';
}
if(postMediaInput){
  postMediaInput.accept='image/jpeg,image/png,image/webp,video/mp4,video/webm,video/quicktime';
  document.querySelector('#imageLabel').textContent='Add photo or video';
  const preview=document.querySelector('#postImagePreview');
  const previewImage=document.querySelector('#postPreviewImage');
  let previewVideo=document.querySelector('#postPreviewVideo');
  if(!previewVideo){previewVideo=document.createElement('video');previewVideo.id='postPreviewVideo';previewVideo.controls=true;previewVideo.playsInline=true;previewVideo.preload='metadata';previewVideo.hidden=true;preview.insertBefore(previewVideo,preview.querySelector('#clearPostImage'));}
  postMediaInput.addEventListener('change',event=>{
    const file=event.target.files[0];
    if(!file?.type.startsWith('video/'))return;
    event.stopImmediatePropagation();
    resetPostMediaPreview();
    document.querySelector('#imageLabel').textContent=file.name;
    postVideoPreviewUrl=URL.createObjectURL(file);
    previewVideo.onloadedmetadata=()=>{preview.hidden=false;previewVideo.hidden=false;};
    previewVideo.onerror=()=>{resetPostMediaPreview();toast('This video could not be previewed.');};
    previewVideo.src=postVideoPreviewUrl;
  },true);
  document.querySelector('#clearPostImage').addEventListener('click',event=>{
    if(!previewVideo.getAttribute('src'))return;
    event.stopImmediatePropagation();
    clearVideoPostSelection();
  },true);
  document.querySelector('#publishPost').addEventListener('click',async event=>{
    const file=postMediaInput.files[0];
    if(!file?.type.startsWith('video/'))return;
    event.preventDefault();
    event.stopImmediatePropagation();
    const supported=['video/mp4','video/webm','video/quicktime'];
    if(!supported.includes(file.type))return toast('Use an MP4, WebM, or MOV video.');
    if(file.size>52428800)return toast('Videos must be 50 MB or smaller.');
    if(!currentUser)return toast('Sign in to publish.');
    const rawText=document.querySelector('#postText').value.trim(),location=document.querySelector('#postLocation').value.trim(),body=[rawText,location?'📍 '+location:''].filter(Boolean).join(' · ')||'🎬';
    const extension=file.name.split('.').pop().toLowerCase(),path=`${currentUser.id}/${Date.now()}.${extension}`;
    const {error:uploadError}=await sqSupabase.storage.from('post-images').upload(path,file,{contentType:file.type});
    if(uploadError)return toast('Could not upload your video.');
    const image_url=sqSupabase.storage.from('post-images').getPublicUrl(path).data.publicUrl;
    const {error}=await sqSupabase.from('posts').insert({author_id:currentUser.id,body,image_url});
    if(error)return toast('Could not publish. Please try again.');
    document.querySelector('#postDialog').close();
    document.querySelector('#postText').value='';
    document.querySelector('#postLocation').value='';
    document.querySelector('#postLocation').hidden=true;
    clearVideoPostSelection();
    await Promise.all([loadPosts(true),loadQuestProgress(),loadGroupQuest()]);
    if(location.pathname.endsWith('/profile.html'))await openUserProfile(currentUser.id);
    toast('Video published! Quest progress updated.');
  },true);
}

